import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for O(1) adjacency checks
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for v in adj[i]:
                if 0 <= v < n:
                    neighbors[i].add(v)

    # Trivial cases
    if n == 1:
        return [0]
    if not any(neighbors[i] for i in range(n)):
        return [0] * n
    complete = True
    for i in range(n):
        if len(neighbors[i]) != n - 1:
            complete = False
            break
    if complete:
        return list(range(n))

    # Precompute degrees and adjacency list
    degrees = [len(neighbors[i]) for i in range(n)]
    adj_list = [list(neighbors[i]) for i in range(n)]

    # Helper: degeneracy ordering (smallest-last) with efficient bucket queue
    def degeneracy_ordering():
        if n == 0:
            return []
        rem_deg = degrees[:]
        removed = [False] * n
        buckets = [[] for _ in range(n)]  # degree 0..n-1
        for v in range(n):
            d = rem_deg[v]
            if d < n:
                buckets[d].append(v)
        order = []
        ptr = 0
        for _ in range(n):
            while ptr < n and not buckets[ptr]:
                ptr += 1
            if ptr >= n:
                break
            v = buckets[ptr].pop()
            while removed[v]:
                if not buckets[ptr]:
                    ptr += 1
                    while ptr < n and not buckets[ptr]:
                        ptr += 1
                    if ptr >= n:
                        break
                    v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    old_d = rem_deg[u]
                    rem_deg[u] -= 1
                    new_d = rem_deg[u]
                    if old_d < n and v in buckets[old_d]:
                        buckets[old_d].remove(v)
                    if new_d < n:
                        buckets[new_d].append(u)
            while ptr < n and not buckets[ptr]:
                ptr += 1
        return order

    # Helper: Welsh-Powell ordering (static degree descending)
    def welsh_powell_ordering():
        return sorted(range(n), key=lambda v: degrees[v], reverse=True)

    # Helper: DSATUR ordering (dynamic saturation degree)
    def dsatur_ordering():
        order = []
        colored = [False] * n
        color = [-1] * n
        sat = [0] * n
        neighbor_colors = [set() for _ in range(n)]
        for _ in range(n):
            max_sat = -1
            candidates = []
            for v in range(n):
                if not colored[v]:
                    if sat[v] > max_sat:
                        max_sat = sat[v]
                        candidates = [v]
                    elif sat[v] == max_sat:
                        candidates.append(v)
            if not candidates:
                for v in range(n):
                    if not colored[v]:
                        candidates.append(v)
                if not candidates:
                    break
            max_deg = -1
            best_v = candidates[0]
            for v in candidates:
                deg_uncolored = 0
                for u in adj_list[v]:
                    if not colored[u]:
                        deg_uncolored += 1
                if deg_uncolored > max_deg:
                    max_deg = deg_uncolored
                    best_v = v
                elif deg_uncolored == max_deg and random.random() < 0.5:
                    best_v = v
            v = best_v
            order.append(v)
            colored[v] = True
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if colored[u] and color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            color[v] = c
            for u in adj_list[v]:
                if not colored[u]:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        sat[u] += 1
        return order

    # Helper: Recursive Largest First (RLF) ordering
    def rlf_ordering():
        order = []
        colored = [False] * n
        color = [-1] * n
        current_color = 0
        while not all(colored):
            R = [v for v in range(n) if not colored[v]]
            if not R:
                break
            max_deg = -1
            v_start = R[0]
            for v in R:
                deg_in_R = 0
                for u in adj_list[v]:
                    if not colored[u]:
                        deg_in_R += 1
                if deg_in_R > max_deg:
                    max_deg = deg_in_R
                    v_start = v
            S = [v_start]
            colored[v_start] = True
            color[v_start] = current_color
            U = set()
            W = set()
            for v in R:
                if v == v_start:
                    continue
                if any(not colored[u] and u in S for u in adj_list[v]):
                    W.add(v)
                else:
                    U.add(v)
            while U:
                best_u = None
                max_w_neighbors = -1
                min_deg_U = float('inf')
                for u in U:
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_U):
                        max_w_neighbors = w_neighbors
                        min_deg_U = deg_in_U
                        best_u = u
                if best_u is None:
                    break
                S.append(best_u)
                colored[best_u] = True
                color[best_u] = current_color
                U.remove(best_u)
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            current_color += 1
        order = []
        for c in range(current_color):
            for v in range(n):
                if color[v] == c:
                    order.append(v)
        return order

    # Helper: Randomized ordering for diversification
    def random_ordering():
        order = list(range(n))
        random.shuffle(order)
        return order

    # Generate orderings
    orders = []
    for order_func in [degeneracy_ordering, welsh_powell_ordering, dsatur_ordering, rlf_ordering, random_ordering]:
        order = order_func()
        if order:
            orders.append(order)

    # Deduplicate orders
    seen = set()
    unique_orders = []
    for order in orders:
        t = tuple(order)
        if t not in seen:
            seen.add(t)
            unique_orders.append(order)
    orders = unique_orders

    # Greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in neighbors[v]:
                if color[u] != -1:
                    if color[u] <= n:
                        used[color[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            color[v] = c
        return color

    # Find best initial coloring
    best_coloring = None
    best_k = float('inf')
    for order in orders:
        col = greedy_color(order)
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_coloring = col
            if best_k == 1:
                break

    if best_coloring is None:
        best_coloring = [0] * n
        best_k = 1 if n > 0 else 0

    # Kempe chain-based local search to reduce color count (optimized)
    def kempe_reduce(coloring, k):
        if k <= 1:
            return coloring, k
        target = k - 1
        # Precompute neighbor color sets for efficiency
        neighbor_colors = [set() for _ in range(n)]
        for v in range(n):
            for u in neighbors[v]:
                if coloring[u] != -1:
                    neighbor_colors[v].add(coloring[u])

        # Try to eliminate color 'target'
        while True:
            verts = [v for v in range(n) if coloring[v] == target]
            if not verts:
                # target color eliminated
                return kempe_reduce(coloring, k - 1)
            made_progress = False
            for v in verts:
                # Try direct reassignment to a lower color
                for c in range(target):
                    if c not in neighbor_colors[v]:
                        # Move v to color c
                        old_color = target
                        coloring[v] = c
                        # Update neighbor_colors for neighbors of v
                        for u in neighbors[v]:
                            neighbor_colors[u].discard(old_color)
                            neighbor_colors[u].add(c)
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chain for each lower color
                for c in range(target):
                    # Skip if adjacent to color c (swap would not help directly)
                    if c in neighbor_colors[v]:
                        continue
                    # Build Kempe chain component for colors {target, c} containing v
                    stack = [v]
                    visited = [False] * n
                    visited[v] = True
                    comp_target = set()
                    comp_c = set()
                    while stack:
                        x = stack.pop()
                        col_x = coloring[x]
                        if col_x == target:
                            comp_target.add(x)
                        elif col_x == c:
                            comp_c.add(x)
                        else:
                            continue
                        for y in neighbors[x]:
                            if not visited[y] and (coloring[y] == target or coloring[y] == c):
                                visited[y] = True
                                stack.append(y)
                    # Check if swap is safe: no edge from comp_c to outside target color
                    safe = True
                    for x in comp_c:
                        for y in neighbors[x]:
                            if coloring[y] == target and y not in comp_target:
                                safe = False
                                break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for x in comp_target:
                            old_col = coloring[x]
                            coloring[x] = c
                            for u in neighbors[x]:
                                neighbor_colors[u].discard(old_col)
                                neighbor_colors[u].add(c)
                        for x in comp_c:
                            old_col = coloring[x]
                            coloring[x] = target
                            for u in neighbors[x]:
                                neighbor_colors[u].discard(old_col)
                                neighbor_colors[u].add(target)
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                # Cannot eliminate target color at this time
                break
        # Recompute k after reduction attempts
        new_max = max(coloring) if n > 0 else -1
        new_k = new_max + 1
        if new_k < k:
            return kempe_reduce(coloring, new_k)
        return coloring, k

    # Apply Kempe reduction
    final_coloring, _ = kempe_reduce(best_coloring[:], best_k)
    return final_coloring

